function pySenti(t){if(typeof PYT!=='string')return null;const P=[...t].map(c=>PYM[c]||null);let best=null,bs=0;for(const k in SPH)for(const w of SPH[k]){const n=w.length;for(let i=0;i+n<=t.length;i++){let sc=0,ex=0,ok=true;for(let j=0;j<n;j++){const x=t[i+j]===w[j]?1:chSim(P[i+j],PYM[w[j]]&&[PYM[w[j]][0]]);if(x<.75){ok=false;break}sc+=x;if(x===1)ex++}if(ok&&ex>=Math.ceil(n/2)&&sc/n>bs){bs=sc/n;best=k}}}return bs>=.86?best:null}
